  // src/overlay/shadow-dom.js
  function createOverlayHost(hideOverlay2) {
    const host = document.createElement("div");
    host.id = "democues-overlay-host";
    const shadowRoot = host.attachShadow({ mode: "open" });
    const style = document.createElement("style");
    style.textContent = getAllStyles();
    const modal = document.createElement("div");
    modal.className = "modal";
    modal.addEventListener("click", (e) => e.stopPropagation());
    const header = document.createElement("div");
    header.className = "modal-header";
    const headerLeft = document.createElement("div");
    headerLeft.className = "header-left";
    const logo = document.createElement("div");
    logo.className = "logo";
    logo.innerHTML = `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/></svg>`;
    const headerTitle = document.createElement("div");
    headerTitle.className = "header-title";
    const title = document.createElement("span");
    title.className = "title";
    title.textContent = "Democues";
    headerTitle.appendChild(title);
    headerLeft.appendChild(logo);
    headerLeft.appendChild(headerTitle);
    const closeButton = document.createElement("button");
    closeButton.className = "close-btn";
    closeButton.setAttribute("aria-label", "Close overlay");
    closeButton.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>`;
    closeButton.addEventListener("click", hideOverlay2);
    header.appendChild(headerLeft);
    header.appendChild(closeButton);
    const content = document.createElement("div");
    content.className = "modal-content";
    modal.appendChild(header);
    modal.appendChild(content);
    shadowRoot.appendChild(style);
    shadowRoot.appendChild(modal);
    return { host, shadowRoot, modal };
  }

  // src/overlay/events.js
  var VALID_VIEWS = ["home", "dashboard"];
  function navigateTo(view, state2, renderCurrentView2) {
    if (!VALID_VIEWS.includes(view)) {
      console.warn(`Democues: Invalid view "${view}", defaulting to home`);
      view = "home";
    }
    state2.currentView = view;
    renderCurrentView2();
  }
  function attachViewEventListeners(shadowRoot, state2, navigateToFn) {
    if (state2.currentView === "home") {
      const cards = shadowRoot.querySelectorAll(".use-case-card");
      cards.forEach((card) => {
        card.addEventListener("click", () => {
          const useCaseId = card.dataset.usecase;
          state2.selectedUseCase = useCaseId;
          navigateToFn("dashboard");
        });
      });
    } else if (state2.currentView === "dashboard") {
      const homeLink = shadowRoot.querySelector('[data-action="go-home"]');
      if (homeLink) {
        homeLink.addEventListener("click", () => navigateToFn("home"));
      }
      const navItemElements = shadowRoot.querySelectorAll(".nav-item");
      navItemElements.forEach((item) => {
        item.addEventListener("click", () => {
          navItemElements.forEach((n) => n.classList.remove("active"));
          item.classList.add("active");
        });
      });
      const taskItems = shadowRoot.querySelectorAll(".task-item");
      taskItems.forEach((item) => {
        item.addEventListener("click", () => {
          const checkbox = item.querySelector(".task-checkbox");
          checkbox.classList.toggle("checked");
          item.classList.toggle("completed");
        });
      });
    }
  }

